function loadCard(workout,preview=false){const computed=preview?computeTrainleafLoad(workout):null,preserved=preview&&workout.loadSnapshot&&JSON.stringify(computed.inputs)===JSON.stringify(workout.loadSnapshot.inputs);const snapshot=preview&&!preserved?computed:workout.loadSnapshot;return `<section class="load-summary"><div class="label-help"><h2>Trainleaf load</h2>${helpButton('trainleaf-load')}</div><strong>${loadDisplay(snapshot)}</strong><p>${snapshot?.inputs?.trainingType==='mental'?'Trening mentalny jest wyłączony z obciążenia fizycznego. Pozostaje w czasie i liczbie treningów.':snapshot?.status==='calculated'?(preview&&!preserved?'Podgląd wyniku. Zapisz go razem z treningiem.':'Zapisany wynik · '+esc(snapshot.algorithm)):esc(loadReasons[snapshot?.reason]||'Ten wpis nie ma zapisanego wyniku.')}</p>${preview?'<small>Możesz zapisać trening także bez wyniku.</small>':''}</section>`}
function progressLoad(rows,label='tydzień'){const summary=loadSummary(rows,demoToday);const text=summary.total===null?'—':new Intl.NumberFormat('pl-PL',{minimumFractionDigits:1,maximumFractionDigits:1}).format(summary.total);return `<section class="load-summary"><div class="label-help"><h2>Trainleaf load · ${esc(label)}</h2>${helpButton('trainleaf-load')}</div><strong>${text}</strong><p>${summary.calculatedCount} z ${summary.completedCount} wykonanych sesji ma zapisany wynik.${summary.missingCount?' Bez wyniku: '+summary.missingCount+'.':''}</p>${summary.mentalCount?'<p>Mentalne: '+summary.mentalCount+' · pozostają w statystykach czasu.</p>':''}${summary.mixedAlgorithms?'<p>Suma zapisanych wyników z różnych wersji algorytmu.</p>':''}</section>`}
