function referenceDaysPreview(reference){return '<dl class="reference-days">'+Array.from({length:7},(_,index)=>{const date=historyDateOffset(reference.source.start,index),sessions=reference.sessions.filter(session=>session.date===date),value=sessions.reduce((sum,session)=>sum+session.value,0),occupied=list().some(workout=>workout.date===date&&!['skipped','deleted'].includes(workout.status)&&!workout.deletedAt);return `<div><dt>${dateLabel(date)}</dt><dd>${sessions.length?new Intl.NumberFormat('pl-PL',{maximumFractionDigits:1}).format(value):reference.source.kind==='planned'?'0 · przykład planu':occupied?'Brak wykonania':'0 · pusty dzień'}</dd></div>`}).join('')+'</dl>'}
function historyConfirmationForm(){const end=day>demoToday?demoToday:historyDateOffset(day,-1);historyConfirmationDraft??={start:historyDateOffset(end,-20),end,confirmed:false};const values=historyConfirmationDraft,candidate=historyConfirmationDays({workouts:list(),...values,today:demoToday});return `<section class="history-completeness"><h2>Kompletność historii</h2><p>Puste dni nie muszą oznaczać odpoczynku. Jeśli wszystkie treningi są już zapisane, możesz potwierdzić cały okres naraz.</p><form id="history-completeness">${field('Początek zakresu','start',values.start,'date',`required max="${demoToday}"`)}${field('Koniec zakresu','end',values.end,'date',`required max="${demoToday}"`)}<div id="history-preview" aria-live="polite">${historyConfirmationPreview(candidate)}</div><label class="choice"><input type="checkbox" name="confirmed" required ${values.confirmed?'checked':''}><span>W tym okresie mam zapisane wszystkie treningi.</span></label><button class="primary wide">Potwierdź kompletność okresu</button></form>${state.historyConfirmations.length?`<p class="form-aside">Ostatnio potwierdzony zakres: ${esc(state.historyConfirmations.at(-1).start)} – ${esc(state.historyConfirmations.at(-1).end)}.</p>`:''}</section>`}
function energySettings(){return back('plan')+heading('Rezerwa w planie','Porównanie rozkładu sesji, na początek każdego dnia.')+`<section class="energy-reference-current">${state.reserveReference?`<p>Stały punkt odniesienia: ${esc(state.reserveReference.source?.start)} – ${esc(state.reserveReference.source?.end)}</p><p class="form-aside">Pozostaje niezmienny przy przesuwaniu sesji.</p>`:'<p>Najpierw wskaż kompletnie zapisany, typowy dla Ciebie tydzień.</p>'}</section><div id="save-error" role="alert"></div><form id="energy-reference">${field('Dowolny dzień wybranego tygodnia','anchor',day,'date','required')}${select('Źródło punktu odniesienia','kind',[{value:'completed',label:'Ukończony typowy tydzień'},{value:'planned',label:'Własny przykładowy plan tygodnia'}],'completed')}${button('Sprawdź wybrany tydzień','data-reference-preview','wide')}<div id="reference-preview" aria-live="polite"></div><label class="choice"><input type="checkbox" name="confirmed" required><span id="reference-confirmation-label">Potwierdzam kompletność tygodnia i brak treningów w jego pustych dniach. Wybieram go jako punkt odniesienia.</span></label><button class="primary wide" id="confirm-reference" disabled>Ustaw punkt odniesienia</button></form>${historyConfirmationForm()}<details><summary>Jak czytać tę symulację?</summary><p>Pasek porównuje rozkład obciążeń w planie. Nie jest procentem energii ani pomiarem regeneracji. Warianty 1, 2 i 3 dni to robocze założenia modelu, a nie przedział ufności.</p><p>Liczymy wcześniejsze 21 dni. Braki pozostają widoczne. Dzisiejsza sesja wpływa na kolejne dni, nie na początek dzisiejszego.</p><p>Kreskowany pasek pokazuje tylko znaną część przy niepełnej historii. Przeszły plan bez wykonania i trening fizyczny bez zapisanego obciążenia pozostają brakami.</p></details>${wellnessEntries().filter(e=>e.date<=demoToday).sort((a,b)=>b.date.localeCompare(a.date))[0]?`<p class="form-aside">Ostatni rzeczywisty check-in: ${esc(wellnessEntries().filter(e=>e.date<=demoToday).sort((a,b)=>b.date.localeCompare(a.date))[0].date)}. Samopoczucie pozostaje osobnym kontekstem.</p>`:''}`}
function iterationClick(b){
 if(view==='wellness'&&b.dataset.go==='wellnessDetail'&&wellnessOriginalKey)selectedWellnessKey=wellnessOriginalKey;
 if(b.dataset.edit||b.dataset.weekSession){openSession(b.dataset.edit||b.dataset.weekSession);return true}
 if(b.dataset.sessionEdit){selectedSessionId=b.dataset.sessionEdit;start(state.workouts.find(w=>w.id===selectedSessionId));return true}
 if(b.dataset.sessionComplete){const w=state.workouts.find(w=>w.id===b.dataset.sessionComplete);if(!w||w.date>demoToday)return true;start(w);draft.planned=clone(w);draft.status='completed';draft.duration='';draft.rpe='';delete draft.postSession;delete draft.loadSnapshot;persist();render();return true}
 if(b.dataset.wellnessEntry){selectedWellnessKey=b.dataset.wellnessEntry;wellnessOrigin=view==='journal'?'journal':'wellnessTrends';nav('wellnessDetail');return true}
 if(b.dataset.editWellness){openWellness(b.dataset.editWellness);return true}
 if(b.hasAttribute('data-checkin')){wellnessOrigin=view==='journal'?'journal':'wellnessTrends';openWellness();return true}
 if(b.dataset.wellnessRange){wellnessRange=b.dataset.wellnessRange;render();document.querySelector('[data-wellness-range="'+wellnessRange+'"]')?.focus();return true}
 if(b.dataset.planMode){planMode=b.dataset.planMode;nav('plan');return true}
 if(b.dataset.planSeason){selectedSeasonId=b.dataset.planSeason;planMode='season';nav('plan');return true}
 if(b.dataset.planWeek){day=b.dataset.planWeek;planMode='week';nav('plan');return true}
 if(b.dataset.planDay){day=b.dataset.planDay;planMode='week';nav('plan');return true}
 if(b.dataset.monthShift){const d=new Date(day+'T12:00:00Z');d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+Number(b.dataset.monthShift));day=d.toISOString().slice(0,10);render();return true}
 if(b.hasAttribute('data-event-new')||b.dataset.eventEdit){eventId=b.dataset.eventEdit||crypto.randomUUID();nav('eventEditor');return true}
 if(b.hasAttribute('data-new-goal')||b.dataset.editGoal){goalId=b.dataset.editGoal||crypto.randomUUID();nav('goalEditor');return true}
 if(b.hasAttribute('data-muscle-target')){selectedMuscleId=b.dataset.muscleId||b.dataset.muscleTarget||null;nav('muscleTargetEditor');return true}
 if(b.hasAttribute('data-muscle-mapping')){const w=state.workouts.find(w=>w.id===b.dataset.sessionId);if(w){returnView='plan';draft=clone(w);mappingOriginalPlan=b.dataset.mappingChannel==='planned'&&w.status==='completed';selectedRolesIndex=(mappingOriginalPlan?draft.planned?.exercises||[]:draft.exercises).findIndex(e=>e.id===b.dataset.exerciseId);if(selectedRolesIndex>=0){persist();nav('exerciseRolesEditor')}else if(!mappingOriginalPlan){persist();nav('editor')}else{notice='Brakuje pierwotnej listy ćwiczeń planu. Wykonanie pozostaje oddzielnym zapisem.';render()}}return true}
 if(b.dataset.exerciseRoles!==undefined){mappingOriginalPlan=false;selectedRolesIndex=Number(b.dataset.exerciseRoles);nav('exerciseRolesEditor');return true}
 if(b.hasAttribute('data-reference-preview')){const f=document.querySelector('#energy-reference'),dates=weekDates(f.elements.anchor.value),r=createReserveReference({workouts:list(),start:dates[0],end:dates[6],today:demoToday,kind:f.elements.kind.value});pendingReference=r.error?null:r;document.querySelector('#confirm-reference').disabled=!pendingReference;if(r.error)showError(r.error);else{document.querySelector('#save-error').textContent='';document.querySelector('#reference-preview').innerHTML='<p><strong>'+dateLabel(dates[0])+' – '+dateLabel(dates[6])+'</strong></p><p>Sesje: '+r.sessions.length+' · zapisane obciążenie: '+new Intl.NumberFormat('pl-PL',{maximumFractionDigits:1}).format(r.value)+'</p>'+referenceDaysPreview(r)+(r.uncompletedPlanCount?'<p>Plany bez wykonania: '+r.uncompletedPlanCount+'. Przeszłe plany pozostają nieznane w prognozie. Potwierdź, że żadne wykonanie nie czeka na zapis.</p>':'')}return true}
 if(b.hasAttribute('data-energy-reference')||b.hasAttribute('data-energy-settings')){pendingReference=null;nav('energySettings');return true}
 return false;
}
function iterationSubmit(form,obj){
 if(form.id==='wellness'){if(!Object.entries(obj).some(([k,v])=>k.startsWith('answer-')&&v!=='')){showError('Uzupełnij przynajmniej jedną odpowiedź.');return true}if(obj.date>demoToday){showError('Check-in opisuje dzisiejszy lub wcześniejszy dzień.');return true}const entries=wellnessEntries().filter(e=>e.date+'|'+e.slot!==wellnessOriginalKey&&(e.date!==obj.date||e.slot!==obj.slot));cacheWellnessForm();selectedWellnessKey=obj.date+'|'+obj.slot;savePatch({wellnessEntries:[...entries,obj],wellness:null},'Check-in zapisany.',wellnessOrigin);return true}
 if(form.id==='event-editor'){if(obj.end<obj.start){showError('Koniec wydarzenia nie może być przed początkiem.');return true}savePatch({events:[...state.events.filter(e=>e.id!==eventId),{...obj,id:eventId,availability:obj.availability||null}]},'Wydarzenie zapisane.','plan');return true}
 if(form.id==='goal-editor'){if(obj['goal-period']==='custom'&&(!obj.start||!obj.end||obj.end<obj.start)){showError('Wybierz prawidłowy zakres celu.');return true}const type=obj['goal-type'],target=Number(obj.target);if(!Number.isFinite(target)||target<=0||(type==='sleepAverageHours'&&target>24)||(['count','activeDays','checkinDays'].includes(type)&&!Number.isInteger(target))){showError('Sprawdź wartość docelową.');return true}savePatch({goals:[...state.goals.filter(g=>g.id!==goalId),{id:goalId,title:obj.title,type,target,period:obj['goal-period']==='week'?'week':{start:obj.start,end:obj.end}}]},'Cel zapisany.','goals');return true}
 if(form.id==='exercise-roles'){const roles={direct:[],indirect:[]};for(const [key,value]of Object.entries(obj))if(key.startsWith('role-')&&['direct','indirect'].includes(value))roles[value].push(key.slice(5));rolesExercise().muscleRoles=roles;persist();notice='Role mięśni zapisane w szkicu.';nav('editor');return true}
 if(form.id==='muscle-target'){const dates=weekDates(day),period=state.periods.find(p=>p.id===obj.scope);if(period&&period.end<weekDates(demoToday)[0]){showError('Dla zakończonego okresu ustaw cel tylko na wybrany tydzień.');return true}const target={muscleId:obj.muscleId,target:Number(obj.target),unit:'effective-sets',source:'user',scope:period?'period':'week',periodId:period?.id||null,start:period?(period.start>weekDates(demoToday)[0]?period.start:weekDates(demoToday)[0]):dates[0],end:period?.end||dates[6],updatedAt:new Date().toISOString()};savePatch({muscleTargets:{...state.muscleTargets,[obj.muscleId+'|'+(period?.id||dates[0])+'|'+Date.now()]:target}},'Cel mięśnia zapisany.','plan');return true}
 if(form.id==='energy-reference'){if(!pendingReference||!obj.confirmed){showError('Najpierw sprawdź i potwierdź wybrany tydzień.');return true}savePatch({reserveReference:{...clone(pendingReference),confirmedComplete:true,confirmedRestDays:pendingReference.source.kind==='completed'?[...(pendingReference.emptyDates||[])]:[]}},'Punkt odniesienia zapisany.','plan');return true}
 if(form.id==='history-completeness'){const candidate=historyConfirmationDays({workouts:list(),start:obj.start,end:obj.end,today:demoToday});if(candidate.error||!obj.confirmed){showError(candidate.error||'Potwierdź, że wszystkie treningi z tego okresu są zapisane.');return true}const record={start:obj.start,end:obj.end,emptyDays:[...candidate.dates],confirmedAt:new Date().toISOString()};if(savePatch({confirmedRestDays:[...new Set([...state.confirmedRestDays,...candidate.dates])].sort(),historyConfirmations:[...state.historyConfirmations,record]},'Kompletność okresu potwierdzona. Brakujące dane sesji pozostają widoczne.','energySettings')){historyConfirmationDraft.confirmed=false;render()}return true}
 return false;
}
document.addEventListener('change',event=>{const t=event.target;if(t.closest('#energy-reference')&&['anchor','kind'].includes(t.name)){pendingReference=null;document.querySelector('#reference-preview').textContent='';document.querySelector('#confirm-reference').disabled=true;document.querySelector('#energy-reference [name=confirmed]').checked=false;document.querySelector('#reference-confirmation-label').textContent=document.querySelector('#energy-reference [name=kind]').value==='planned'?'Wybieram ten przykładowy plan jako punkt odniesienia. Nie potwierdza on mojej historii treningów.':'Potwierdzam kompletność tygodnia i brak treningów w jego pustych dniach. Wybieram go jako punkt odniesienia.'}if(t.closest('#history-completeness')){const form=t.closest('form');if(t.name!=='confirmed')form.elements.confirmed.checked=false;historyConfirmationDraft={start:form.elements.start.value,end:form.elements.end.value,confirmed:form.elements.confirmed.checked};document.querySelector('#history-preview').innerHTML=historyConfirmationPreview(historyConfirmationDays({workouts:list(),...historyConfirmationDraft,today:demoToday}))}if(t.name==='plan-search'||t.name==='plan-trainingtype'){planFilters[t.name==='plan-search'?'search':'trainingType']=t.value;render();document.querySelector('.plan-filters').open=true;document.querySelector('[name="'+t.name+'"]')?.focus()}if(t.name==='wellness-trend-slot'){wellnessSlot=t.value;wellnessMetric=t.value==='Rano'?'Sen (godziny)':t.value==='Wieczorem'?'Zmęczenie':'Energia';render()}if(t.name==='wellness-trend-metric'){wellnessMetric=t.value;render()}if(t.name==='goal-type'){const input=document.querySelector('[name=target]'),sleep=t.value==='sleepAverageHours';input.step=sleep?'.25':'1';input.min=sleep?'.25':'1';sleep?input.max='24':input.removeAttribute('max')}if(t.name==='goal-period')document.querySelector('#goal-dates').hidden=t.value!=='custom'});
helpTexts['energy-calendar'][2]=[{label:'Badanie obciążenia i samopoczucia u rugbystów',url:'https://pubmed.ncbi.nlm.nih.gov/39758184/'},{label:'Konsensus: indywidualność regeneracji',url:'https://pubmed.ncbi.nlm.nih.gov/29345524/'}];
bindHelp();
document.addEventListener('click',event=>{
 const b=event.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-help')||b.hasAttribute('data-close-help'))return;
 notice='';if(iterationClick(b))return;
 if(draft){const action=handleExerciseClick(b,draft);if(action?.handled){if(action.changed)persist();render();if(action.focusSelector)document.querySelector(action.focusSelector)?.focus();return}}
 if(b.hasAttribute('data-skip-feeling')){const range=b.closest('.feeling').querySelector('.feeling-range');range.value=Math.round((Number(range.min)+Number(range.max))/2);syncPost(range,true);return}
 notice='';
 if(b.hasAttribute('data-checkin')){returnView=view==='journal'?'journal':'more';day=demoToday;nav('wellness')}
 else if(b.dataset.go){if(b.dataset.go==='library')picking=false;if(b.dataset.go==='wellness'){nav('wellnessTrends');return}nav(b.dataset.go)}
 else if(b.hasAttribute('data-today-week')){todayExpanded=!todayExpanded;render()}
 else if(b.hasAttribute('data-new')){day=demoToday;start()}
 else if(b.hasAttribute('data-plan'))start(null,true);
 else if(b.dataset.edit||b.dataset.weekSession)start(state.workouts.find(w=>w.id===(b.dataset.edit||b.dataset.weekSession)));
 else if(b.dataset.weekDate){day=b.dataset.weekDate;planMode='week';if(view==='journal')nav('plan');else render();document.querySelector('[data-week-date="'+day+'"]')?.focus()}
 else if(b.dataset.weekShift){const date=new Date(day+'T12:00:00');date.setDate(date.getDate()+Number(b.dataset.weekShift)*7);day=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;render();document.querySelector('[data-week-shift="'+b.dataset.weekShift+'"]')?.focus()}
 else if(b.dataset.history){historyTab=b.dataset.history;historyMonth='';historyLimit=20;render()}
 else if(b.dataset.progressRange){progressRange=b.dataset.progressRange;render();document.querySelector('[data-progress-range="'+progressRange+'"]')?.focus()}
 else if(b.hasAttribute('data-more-history')){historyLimit+=20;render();document.querySelector('[data-more-history]')?.focus({preventScroll:true})}
 else if(b.hasAttribute('data-more-wellness')){wellnessLimit+=20;render();document.querySelector('[data-more-wellness]')?.focus({preventScroll:true})}
 else if(b.dataset.period){periodId=b.dataset.period;nav('period')}
 else if(b.hasAttribute('data-period-new')){periodId=crypto.randomUUID();nav('period')}
 else if(b.hasAttribute('data-picker')){picking=true;nav('library')}
 else if(b.dataset.exercise!==undefined){selectedExercise=Number(b.dataset.exercise);nav('detail')}
 else if(b.hasAttribute('data-add-exercise')||b.hasAttribute('data-create-exercise')){if(!draft)start();draft.exercises.push(prepareExercise(catalog[selectedExercise]));persist();nav('editor')}
 else if(b.hasAttribute('data-complete')){if(draft.date>demoToday)return;draft.planned=clone(draft);draft.status='completed';draft.duration='';draft.rpe='';persist();render()}
 else if(b.hasAttribute('data-convert-plan')){draft.status='planned';persist();render()}
 else if(b.hasAttribute('data-copy')){draft.id=crypto.randomUUID();draft.title+=' (kopia)';draft.date=day;draft.status='planned';delete draft.postSession;delete draft.planned;delete draft.loadSnapshot;persist();notice='Nowy szkic. Oryginał pozostaje bez zmian.';render()}
 else if(b.hasAttribute('data-skip-review'))saveDraft();
 else if(b.dataset.template){if(!draft)start(null,true);const ids=b.dataset.template==='whole'?[4,0,1,4]:[4];draft.exercises.push(...ids.map((i,j)=>({...prepareExercise(catalog[i]),section:j===0?'warmup':j===ids.length-1&&ids.length>1?'cooldown':'main'})));if(!draft.title)draft.title=b.dataset.template==='whole'?'Siła całego ciała':'Mobilna rozgrzewka';persist();nav('editor')}
});
document.addEventListener('input',event=>{
 const t=event.target;
 if(t.closest('#wellness')&&!['slot','date'].includes(t.name))cacheWellnessForm();
 if(t.matches('.feeling-range')){syncPost(t);return}
 if(t.closest('#workout')&&draft&&t.name?.startsWith('expected-')){updateExpected(t);return}
 if(t.closest('#workout')&&draft){if(handleExerciseInput(t,draft)){persist();return}if(t.name){draft[t.name]=t.value;persist();if(t.name==='date')updateFutureState();if(t.name==='trainingType')document.querySelector('#chosen-type').innerHTML=typeBadge(draft)}}
 if(t.name==='post-notes'&&draft){draft.postSession.notes=t.value;persist();refreshLoadPreview()}
 if(t.name==='search'){query=t.value;document.querySelector('#exercise-list').innerHTML=exerciseList()}
});
