document.addEventListener('submit',event=>{
 event.preventDefault();const form=event.target,d=new FormData(form),obj=Object.fromEntries(d);
 if(iterationSubmit(form,obj))return;
 if(form.id==='workout'){if(draft.status==='completed'){if(draft.date>demoToday)return;persist();nav('postSession')}else saveDraft()}
 else if(form.id==='post-session')saveDraft();
 else if(form.id==='profile'){const result=readProfile(form,state.profile);if(result.error){showError(result.error);return}state.profile=result.profile;persist();notice='Zapisano sporty.';nav(draft?'editor':'more')}
 else if(form.id==='modules'){state.profile=readModules(form,state.profile);persist();notice='Zapisano skróty. Dane pozostają dostępne.';nav('more')}
 else if(form.id==='period'){if(obj.end<obj.start){form.elements.end.setCustomValidity('Koniec nie może być przed początkiem.');form.elements.end.reportValidity();form.elements.end.oninput=()=>form.elements.end.setCustomValidity('');return}let ancestor=obj.parentId;const visited=new Set([periodId]);while(ancestor){if(visited.has(ancestor)){showError('Okres nie może być swoim przodkiem. Zmień okres nadrzędny.');return}visited.add(ancestor);ancestor=state.periods.find(p=>p.id===ancestor)?.parentId}state.periods=[...state.periods.filter(p=>p.id!==periodId),{...obj,id:periodId,parentId:obj.parentId||null}];persist();notice='Zapisano okres.';nav('periods')}
 else if(form.id==='goal'){state.goal=obj.goal;persist();nav('journal')}
 else if(form.id==='wellness'){if(!Object.entries(obj).some(([k,v])=>k.startsWith('answer-')&&v!=='')){showError('Uzupełnij przynajmniej jedną odpowiedź.');return}state.wellnessEntries=[...wellnessEntries().filter(x=>x.date!==obj.date||x.slot!==obj.slot),obj];state.wellness=obj;persist();notice='Zapisano check-in.';nav(returnView)}
 else if(form.id==='exercise-note'){state.exerciseNotes={...state.exerciseNotes,[catalog[selectedExercise].name]:obj.exerciseNote};persist();notice='Zapisano notatkę.';render()}
 else if(form.id==='custom'){const entry={...obj,id:crypto.randomUUID(),muscles:obj.muscles.split(',').map(x=>x.trim()).filter(Boolean)};catalog.push(entry);state.customExercises.push(entry);persist();notice='Dodano własne ćwiczenie.';nav('library')}
 else if(form.id==='export'){const csv=obj.format==='csv',safe=x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const content=csv?'\ufeff'+[['Data','Trening','Rodzaj','Dyscyplina','Status','Minuty','RPE','Zmęczenie oddechowe','Zmęczenie mięśniowe','Satysfakcja','Trainleaf load','Wersja load'],...state.workouts.map(w=>[w.date,w.title,typeOf(w).label,w.sport,w.status,w.duration,w.rpe,w.postSession?.aerobic,w.postSession?.muscular,w.postSession?.satisfaction,w.loadSnapshot?.value,w.loadSnapshot?.algorithm])].map(r=>r.map(safe).join(';')).join('\r\n'):JSON.stringify({format:'ui-prototype-only',...state,draft},null,2),url=URL.createObjectURL(new Blob([content],{type:csv?'text/csv;charset=utf-8':'application/json'})),a=document.createElement('a');a.href=url;a.download='Trainleaf-prototyp-dane.'+(csv?'csv':'json');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice='Przekazano plik do pobrania.';render()}
});
